<script setup lang="ts">
import {onMounted,ref} from 'vue'
import PageHeader from '../../components/common/PageHeader.vue'
import AppSelect from '../../components/common/AppSelect.vue'
import {reviews,roleNames,type Application} from '../../api/accountReviews'
const rows=ref<Application[]>([]),selected=ref<Application|null>(null),status=ref('pending'),page=ref(1),total=ref(0),loading=ref(false),busy=ref(false),error=ref(''),notice=ref('')
const role=ref('user'),qualification=ref(''),validUntil=ref(''),note=ref('')
let generation=0
async function load(reset=false){if(reset)page.value=1;selected.value=null;const current=++generation;loading.value=true;error.value='';try{const data=await reviews.list(status.value,page.value);if(current!==generation)return;rows.value=data.items;total.value=data.total}catch(e){if(current===generation)error.value=e instanceof Error?e.message:'读取失败'}finally{if(current===generation)loading.value=false}}
function choose(row:Application){selected.value=row;role.value=row.requested_role||'user';qualification.value='';validUntil.value='';note.value='';notice.value=''}
async function decide(action:'approve'|'reject'){const row=selected.value;if(!row||busy.value)return;if(action==='reject'&&!note.value.trim()){error.value='请填写未通过原因';return}if(!window.confirm(action==='approve'?`确认开通${roleNames[role.value]}岗位？该账号需重新登录。`:'确认本次申请未通过？'))return;busy.value=true;error.value='';try{await reviews.decide(row.id,{version:row.application_version,action,role:role.value,note:note.value.trim(),qualification:qualification.value.trim(),valid_until:validUntil.value||null});await load();notice.value=action==='approve'?'申请已通过，请通知申请人重新登录；护工还需分配负责老人。':'审核结果已保存，申请人可查看原因并重新申请。'}catch(e){error.value=e instanceof Error?e.message:'审核失败'}finally{busy.value=false}}
async function setStatus(){const row=selected.value;if(!row||busy.value)return;if(!note.value.trim()){error.value='请填写账号状态调整原因';return}const next=row.status==='active'?'disabled':'active';if(!window.confirm(next==='disabled'?'停用后该账号将立即失去登录和业务访问权限，确定继续吗？':'确认恢复账号使用？专业岗位仍须通过资质有效期检查。'))return;busy.value=true;error.value='';try{await reviews.status(row.id,{version:row.application_version,status:next,note:note.value.trim()});await load();notice.value='账号状态已更新，原会话已失效。'}catch(e){error.value=e instanceof Error?e.message:'更新失败'}finally{busy.value=false}}
onMounted(()=>void load())
</script>
<template><div class="page account-reviews"><PageHeader title="注册审核与账号状态" subtitle="核实人员身份、申请岗位与任职资质，通过后才开通业务权限。"/><p v-if="error" class="review-message error" role="alert">{{ error }}</p><p v-if="notice" class="review-message success" role="status">{{ notice }}</p><div class="card review-toolbar"><label>账号状态<AppSelect v-model="status" class="select" :disabled="busy" @change="load(true)"><option value="pending">待审核</option><option value="rejected">未通过</option><option value="active">已开通</option><option value="disabled">已停用</option></AppSelect></label><button class="btn" :disabled="busy||loading" @click="load()">刷新列表</button><span>共 {{ total }} 个账号</span></div>
<div class="review-columns"><section class="card review-panel"><h2>{{ {pending:'待审核申请',rejected:'未通过申请',active:'已开通账号',disabled:'已停用账号'}[status] }}</h2><p v-if="loading" role="status">正在读取…</p><p v-else-if="!rows.length">暂无相关账号。</p><button v-for="row in rows" :key="row.id" type="button" class="review-item" :class="{selected:selected?.id===row.id}" :disabled="busy||loading" @click="choose(row)"><span><b>{{ row.name }}</b><small>{{ row.phone_hint }}</small></span><span>{{ status==='pending'||status==='rejected'?roleNames[row.requested_role||'user']:roleNames[row.role||'user'] }}</span></button><div class="review-actions"><button class="btn" :disabled="page<=1||busy||loading" @click="page--;load()">上一页</button><span>第 {{ page }} 页</span><button class="btn" :disabled="page*20>=total||busy||loading" @click="page++;load()">下一页</button></div></section>
<section v-if="selected" class="card review-panel"><h2>{{ selected.name }} · {{ selected.phone_hint }}</h2><p>申请岗位：{{ roleNames[selected.requested_role||selected.role||'user'] }}</p><p class="review-note">申请说明：{{ selected.application_note||'未填写' }}</p><p v-if="selected.review_note">上次审核意见：{{ selected.review_note }}</p><fieldset :disabled="busy"><template v-if="selected.status==='pending'"><label>实际授予岗位<AppSelect v-model="role" class="select"><option v-for="id in ['user','medical','kitchen','nursing','finance']" :key="id" :value="id">{{ roleNames[id] }}</option></AppSelect></label><template v-if="['medical','nursing'].includes(role)"><label>资质 / 任职核实记录（必填）<input v-model="qualification" class="input" maxlength="80" placeholder="填写核实依据或资质记录编号"></label><label>资质有效期（必填）<input v-model="validUntil" class="input" type="date"></label></template><label>审核意见（未通过时必填）<textarea v-model="note" class="input" rows="3" maxlength="1000"/></label><div class="review-actions"><button class="btn primary" :disabled="busy||(['medical','nursing'].includes(role)&&(!qualification.trim()||!validUntil))" @click="decide('approve')">通过并开通</button><button class="btn" :disabled="busy||!note.trim()" @click="decide('reject')">未通过</button></div><p class="review-help">院长账号不开放注册。护工通过审核后，还需要由护理部在“护工账号与分配”中分配老人。</p></template><template v-else-if="selected.status==='active'||selected.status==='disabled'"><p>当前岗位：{{ roleNames[selected.role||'user'] }}。此处可管理账号启停，护工负责老人由护理部分配。</p><label>状态调整原因<textarea v-model="note" class="input" rows="3" maxlength="1000"/></label><button class="btn" :disabled="busy||!note.trim()" @click="setStatus">{{ selected.status==='active'?'停用账号':'恢复使用' }}</button></template><p v-else>申请人补充资料并重新提交后，会回到待审核列表。</p></fieldset></section></div></div></template>
<style scoped>.account-reviews{max-width:1240px;margin:auto}.review-toolbar{display:flex;align-items:end;gap:20px;flex-wrap:wrap;padding:20px;margin:20px 0}.review-toolbar label{min-width:180px}.review-columns{display:grid;grid-template-columns:minmax(280px,1fr) minmax(0,1.4fr);gap:20px;align-items:start}.review-panel{padding:24px;min-width:0}.review-panel h2{font-size:18px;margin:0 0 20px}.review-panel p{line-height:1.9;overflow-wrap:anywhere}label{display:grid;gap:8px;margin:14px 0}fieldset{border:0;padding:0;margin:0;min-width:0}.review-item{display:flex;justify-content:space-between;gap:12px;align-items:center;padding:16px 12px;width:100%;border:0;border-bottom:1px solid var(--line);background:transparent;text-align:left;border-radius:8px;cursor:pointer;color:inherit}.review-item.selected{background:#edf3ff}.review-item small{display:block;color:#64748b;margin-top:8px}.review-actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:20px 0}.review-note{background:#f5f7fc;padding:16px;border-radius:10px}.review-help{color:#64748b;font-size:13px}.review-message{padding:14px 18px;border-radius:10px}.review-message.error{background:#fff0f0;color:#a12d2d}.review-message.success{background:#eaf8f0;color:#24613e}.btn,.review-item{min-height:44px}:focus-visible{outline:2px solid var(--brand);outline-offset:3px}@media(max-width:900px){.review-columns{grid-template-columns:1fr}}</style>
